/**
 * Discovery learns a mount's namespace from its file name, after the mount
 * call ran. This hidden setter on the mount hands that namespace back to the
 * extension handle (`extension.namespace`).
 */
const SET_NAMESPACE = Symbol.for("cursor.bdk.extensionSetNamespace");
export function attachNamespaceSetter(mount, set) {
    Object.defineProperty(mount, SET_NAMESPACE, { value: set });
}
export function recordMountNamespace(mount, namespace) {
    if (SET_NAMESPACE in mount && typeof mount[SET_NAMESPACE] === "function") {
        mount[SET_NAMESPACE](namespace);
    }
}
